def close_duplicate_open_alerts(apps, schema_editor):
    """Перед уникальным индексом: если в базе уже есть несколько ОТКРЫТЫХ сигналов по одному правилу и пациенту
    (могли появиться в первой версии при одновременных событиях), оставляем открытым самый свежий,
    остальные помечаем закрытыми с пояснением."""
    Alert = apps.get_model("alerts", "Alert")
    open_statuses = ("new", "delivered", "escalated")
    seen = set()
    for a in Alert.objects.filter(status__in=open_statuses).order_by("-created_at", "-id"):
        key = (a.patient_id, a.rule_id)
        if key in seen:
            Alert.objects.filter(id=a.id).update(status="resolved", resolution="закрыт автоматически: дубль открытого сигнала")
        else:
            seen.add(key)


